int sum = 0;
for (int i = 1; i <= 5; ++i) {
    if (i == 3) break;
    sum += i;
}
cout << sum << endl;

void compute(int &a, int &b, int c = 10) {
    int temp = a;
    a = b + c;
    b = temp * c;
    c = b - a;
}
int main() {
    int x = 1, y = 2, z = 3;
    compute(z, x);
    compute(x, y, z);
    cout << x << " " << y << " " << z << endl;
    return 0;
}
